package com.lianxibu.site.service.jobs;

import com.lianxibu.site.domain.protocol.*;
import com.lianxibu.site.repository.jobs.*;
import com.lianxibu.site.service.articles.EntityDedupService;
import java.time.*;
import java.util.*;
import tools.jackson.databind.json.JsonMapper;

/** Pure exact original P1 input/result/automatic-command linkage. Native storage and source admission remain caller obligations. */
public final class EntityHeatDedupOrigin {
    public record Origin(String eventId,String itemId,String entityId,String rootId,String inputHash,String resultHash,String requestHash,String sourceId,String runId,String sourceItemId,LocalDate day,String originalBodyHash,String originalBodyJson){@Override public String toString(){return "OriginalEntityDedupOriginFacts[redacted]";}}
    private EntityHeatDedupOrigin(){ }
    public static Origin bind(JdbcEntityHeatEvents.Event event,SourcePartitionPlanner.Chunk chunk,SourceDedupFragmentProof fragment){
        Objects.requireNonNull(event);Objects.requireNonNull(chunk);Objects.requireNonNull(fragment);if(!"analysis-worker".equals(event.actor())||event.actedAt()==null||event.actedAt().getNano()%1000!=0||!chunk.rootId().equals(fragment.rootId())||!chunk.inputHash().equals(fragment.result().inputHash()))throw invalid();
        var snapshot=CanonicalJson.parse(chunk.snapshotJson());var context=FrozenApplicationContext.fromJson(snapshot.get(FrozenApplicationContext.FIELD));var input=context.input(chunk.rootId(),"entity-origin-reader",chunk.inputHash(),0);if(input.stage()!=GenerationFlowService.Stage.NEWS_DEDUP)throw invalid();var bindings=FrozenMemberBindings.read(snapshot,input);var receipt=EntityDecisionJdbcLog.decodeReceiptPayload(event.payloadJson(),event.reason());if(!"entity-decision-v2".equals(receipt.schema())||!Set.of("new","existing","needs_review").contains(receipt.operation())||receipt.oldId()!=null||!event.payloadHash().equals(HexFormat.of().formatHex(JdbcGenerationLineage.hash(JdbcFrozenInputs.canonical(CanonicalJson.parse(event.payloadJson()))))))throw invalid();
        var fields=Set.of("kind","id");var target=CanonicalJson.parse(event.targetJson());WireValues.object(target,fields,fields);String id=receipt.itemId();if(!"source_run_item".equals(WireValues.text(target.get("kind")))||!id.equals(WireValues.id(target.get("id"),false))||!event.id().equals(eventId(fragment.rootId(),fragment.result().resultHash(),id)))throw invalid();
        var member=bindings.get(id);var facts=fragment.members().stream().filter(m->m.itemId().equals(id)).toList();var values=CanonicalJson.parse(fragment.result().payloadJson()).get("items").valueStream().filter(v->v.get("item_id").asText().equals(id)).toList();var bodies=snapshot.get("members").valueStream().filter(m->m.get("id").asText().equals(id)).toList();if(member==null||facts.size()!=1||values.size()!=1||bodies.size()!=1||!"news_tech".equals(member.category()))throw invalid();var value=values.getFirst();var fact=facts.getFirst();var body=bodies.getFirst().get("body");String hash=CanonicalJson.hash(CanonicalJson.Domain.CONTENT,body);if(!hash.equals(WireValues.sha256(bodies.getFirst().get("body_hash"))))throw invalid();
        var command=new EntityDedupService.Automatic(id,member.expectedRevision(),WireValues.text(value.get("decision")),member.category(),member.identityKey(),value.get("candidate_entity_id").isNull()?null:WireValues.id(value.get("candidate_entity_id"),false),input.candidatesByItem().getOrDefault(id,Set.of()).stream().sorted().toList(),WireValues.text(value.get("suggested_title")),value.get("suggested_summary").isNull()?null:WireValues.text(value.get("suggested_summary")),WireValues.text(value.get("reason")));
        if(!receipt.requestHash().equals(EntityDedupService.automaticFingerprint(command))||!event.reason().equals(command.reason())||!Objects.equals(receipt.result().entityId(),fact.entityId())||!receipt.result().state().equals(fact.state())||!Objects.equals(receipt.newId(),fact.entityId())||!"news_tech".equals(fact.category())||"new".equals(receipt.operation())&&(!"new".equals(command.decision())||!member.newEntityId().equals(receipt.newId()))||"existing".equals(command.decision())&&!Objects.equals(command.proposedEntityId(),receipt.newId())||"needs_review".equals(command.decision())!= "needs_review".equals(receipt.operation()))throw invalid();
        for(var heat:receipt.snapshots())if(heat.firstRecordedAt()!=null&&heat.firstRecordedAt().isAfter(event.actedAt()))throw invalid();return new Origin(event.id(),id,fact.entityId(),chunk.rootId(),chunk.inputHash(),fragment.result().resultHash(),receipt.requestHash(),fact.sourceId(),fact.runId(),fact.sourceItemId(),fact.businessDate(),hash,JdbcFrozenInputs.canonical(body));
    }
    public static String eventId(String root,String resultHash,String item){WireValues.id(root,false);WireValues.id(item,false);if(resultHash==null||!resultHash.matches("[0-9a-f]{64}"))throw invalid();var key=JsonMapper.shared().createObjectNode().put("scope","dedup-member-v1").put("root_id",root).put("result_hash",resultHash).put("item_id",item);var identity=JsonMapper.shared().createObjectNode().put("scope","entity-decision-v1").put("actor_id","analysis-worker").put("action_key",CanonicalJson.hash(CanonicalJson.Domain.ACTION,key));return CanonicalJson.hash(CanonicalJson.Domain.ACTION,identity);}
    private static IllegalStateException invalid(){return new IllegalStateException("exact original dedup count event linkage unavailable");}
}
